  '2–5 yaş için günde en fazla 1 saat, yaşa uygun ve mümkünse birlikte izlenen içerik önerilir.': 'Entre 2 et 5 ans, au maximum 1 heure par jour de contenus adaptés, idéalement regardés ensemble, est recommandée.',
