  'Adet başlangıç tarihlerini kişisel günlüğüne kaydet. Bu kayıtlar cihazın korumalı yerel depolamasında saklanır; otomatik bulut yedeklemesi yapılmaz. Döngü tahmini, doğurganlık hesabı ya da tıbbi değerlendirme yapılmaz.': 'Enregistrez les dates de début de vos règles dans votre journal personnel. Ces données sont conservées dans le stockage local protégé de l\'appareil ; aucune sauvegarde cloud automatique n\'est faite. Aucune prévision de cycle, calcul de fertilité ni évaluation médicale n\'est effectué.',
