  'Adet döngüsü geçmişim': 'Historique de mes règles',
  'Adet gecikmesi, hafif kramp veya az miktarda lekelenme olabilir. Ev gebelik testi pozitif çıkabilir.': 'Retard de règles, légères crampes ou petit saignement sont possibles. Un test de grossesse peut être positif.',
