  'Aile sofrasına az tuzlu, yaşa uygun kıvamda katıl. Günde 3 öğün + 2 ara öğün. Günlük süt yaklaşık 2 su bardağını aşmamalı. Emzirme isteğe bağlı olarak sürebilir. Seçici yeme bu yaşta olağandır.': 'Participer aux repas familiaux, peu salés et de texture adaptée. 3 repas + 2 collations par jour. Le lait ne devrait pas dépasser environ 2 verres par jour. L\'allaitement peut continuer selon les souhaits. La sélectivité est normale à cet âge.',
