  'Balkabağını ve mercimeği ekleyip 2 dakika karıştırın.': 'Ajoutez potiron et lentilles et remuez 2 minutes.',
  'Balkabağının tatlılığı limonla dengelenir; servis sırasında mutlaka limon sıkın.': 'La douceur du potiron est équilibrée par le citron ; pressez-en toujours au service.',
