  'Balık': 'Poisson',
  'Balık eti opaklaşıp kolay ayrılana kadar 18-22 dakika pişirin.': 'Enfournez 18-22 minutes jusqu’à ce que le poisson soit opaque et s’effeuille.',
  'Balık eti tamamen pişip kolay ayrılana kadar 25-30 dakika fırınlayın.': 'Enfournez 25-30 minutes jusqu’à ce que le poisson soit cuit et s’effeuille.',
  'Balık kokulu gri akıntı bakteriyel vajinozu düşündürebilir.': 'Des pertes grises à odeur de poisson peuvent évoquer une vaginose bactérienne.',
  'Balık köftesi': 'Croquettes de poisson',
  'Balık opaklaşıp kolay ayrılana kadar yaklaşık 15-20 dakika pişirin.': 'Enfournez environ 15-20 minutes jusqu’à ce que le poisson soit opaque et s’effeuille.',
  'Balık parçalarını tuz ve karabiberle tatlandırıp sebzelerin arasına yerleştirin, kalan sosu üzerine gezdirin.': 'Assaisonnez le poisson de sel et poivre, placez-le entre les légumes et nappez du reste de sauce.',
  'Balık tamamen pişene kadar 18-22 dakika fırınlayıp maydanozla servis edin.': 'Enfournez 18-22 minutes jusqu’à cuisson complète et servez avec du persil.',
  'Balık tamamen pişene kadar 20-25 dakika fırınlayıp maydanozla servis edin.': 'Enfournez 20-25 minutes jusqu’à cuisson complète et servez avec du persil.',
  'Balık tamamen pişene ve eti kolay ayrılana dek yaklaşık 18–22 dakika pişirin.': 'Enfournez environ 18–22 minutes jusqu’à ce que le poisson soit cuit et s’effeuille.',
  'Balık tamamen pişip kolay ayrılana kadar yaklaşık 18–22 dakika fırınlayın.': 'Enfournez environ 18–22 minutes jusqu’à ce que le poisson soit cuit et s’effeuille.',
  'Balık ve deniz ürünleri': 'Poissons et fruits de mer',
  'Balık, eti çatalla kolayca ayrılıyorsa pişmiştir; fazla pişirmek kurutur.': 'Le poisson est cuit quand la chair s\'effeuille facilement à la fourchette ; trop cuit, il se dessèche.',
  'Balıkları temizleyip kağıt havluyla kurulayın.': 'Nettoyez le poisson et séchez-le avec du papier absorbant.',
  'Balıkları temizleyip kurulayın.': 'Nettoyez et séchez le poisson.',
  'Balıkları temizleyip kılçık kontrolü yapın.': 'Nettoyez le poisson et vérifiez les arêtes.',
  'Balıkları yağlayıp içlerine maydanoz koyun.': 'Huilez le poisson et glissez du persil à l’intérieur.',
  'Balıkları üzerine yerleştirip limon ve yağ ekleyin.': 'Posez le poisson dessus et ajoutez citron et huile.',
  'Balıkların karnına sarımsak dilimleri, maydanoz sapları ve 2 dilim limon yerleştirin.': 'Glissez l’ail émincé, les tiges de persil et 2 rondelles de citron dans le ventre des poissons.',
  'Balıkların üzerine kalan zeytinyağını gezdirin, 2\'şer dilim limon yerleştirin.': 'Arrosez les poissons du reste d’huile et posez 2 rondelles de citron sur chacun.',
  'Balıklı sebze güveç': 'Cocotte de poisson aux légumes',
  'Balıksız sebzeli bulgur': 'Boulgour aux légumes (sans poisson)',
  'Balığı sebzelerle birlikte başta koyarsanız fazla pişip dağılır; son 15 dakikada ekleyin.': 'Mis au début avec les légumes, le poisson cuit trop et se défait ; ajoutez-le dans les 15 dernières minutes.',
  'Balığı çevirirken iki spatula kullanmak dağılmasını önler.': 'Utiliser deux spatules pour retourner le poisson évite qu’il se défasse.',
  'Balığın gözü beyazlaşıp dışarı çıkıyorsa pişmiştir.': 'Le poisson est cuit quand l’œil blanchit et ressort.',
  'Balığın içini ve dışını tuz, karabiber ve 2 yemek kaşığı zeytinyağı ile ovun; karnına 2 dilim limon ve kekik dallarını yerleştirin.': 'Frottez le poisson dedans et dehors de sel, poivre et 2 c. à soupe d’huile d’olive ; glissez 2 rondelles de citron et le thym dans le ventre.',
  'Bamya yemeği': 'Ragoût de gombos',
  'Bamyaları ekleyin; şeker ve sıcak suyu ilave edin, bamyalar dağılmasın diye karıştırmadan tencereyi sallayın.': 'Ajoutez gombos, sucre et eau chaude ; secouez la casserole au lieu de remuer pour que les gombos restent entiers.',
  'Bamyaları geniş bir kapta limon suyu ve tuzla harmanlayıp 15 dakika bekletin, ardından yıkayıp süzün.': 'Mélangez les gombos avec jus de citron et sel dans un grand bol, laissez 15 minutes puis lavez et égouttez.',
  'Bamyaları yıkayıp saplarını koni biçiminde ayıklayın.': 'Lavez les gombos et taillez les pédoncules en cône.',
  'Bamyaları, limon suyunu ve suyu ilave edin.': 'Ajoutez les gombos, le jus de citron et l’eau.',
  'Bamyaların şapkalarını konik şekilde, iç kısmı açılmadan kalemtıraş gibi açın.': 'Taillez le chapeau des gombos en cône, comme un taille-crayon, sans ouvrir l’intérieur.',
  'Bamyayı kaşıkla karıştırmayın; tencereyi sallayın.': 'Ne remuez pas les gombos à la cuillère ; secouez la casserole.',
