  'Banyo sonrası nefes alma güçlüğü veya morarma.': 'Difficulté à respirer ou coloration bleue après le bain.',
  'Banyo suyu 36–37 °C civarında olmalıdır; dirsekle kontrol et.': 'L\'eau du bain doit être autour de 36–37 °C ; vérifiez-la avec le coude.',
