  'Banyo, beslenme, ninni gibi her akşam aynı sırayla yapılan kısa bir rutin oluştur.': 'Créez une courte routine répétée chaque soir dans le même ordre, comme bain, tétée et berceuse.',
  'Banyo, cilt bakımı ve bez değişimi gibi rutinleri çocuğun ihtiyacına göre düzenleyin.': 'Adaptez les routines comme le bain, les soins de la peau et le change aux besoins de votre enfant.',
