  'Başını daha dik tutar; ellerini birleştirip ağzına götürür. Kahkahaya yakın sesler, renkli nesnelere uzun bakma.': 'Tient la tête plus droite ; rapproche ses mains et les porte à la bouche. Rit presque, regarde plus longtemps les objets colorés.',
  'Başını dik ve sabit tutar; nesnelere uzanır ve tutar. Kahkaha atar, yüzüstüyken kollarıyla doğrulur. Yuvarlanma denemeleri başlayabilir.': 'Tient la tête droite et stable ; attrape et tient les objets. Rit, se redresse sur les bras à plat ventre. Les tentatives de retournement peuvent commencer.',
