  'Bebek bakımı': 'Soins du bébé',
  'Bebek bakımı sırasında uyku bölünmesi kaçınılmazdır; ama uzun süreli uykusuzluk ruh sağlığını etkiler.': 'Un sommeil haché est inévitable avec un bébé, mais un manque de sommeil prolongé affecte la santé mentale.',
  'Bebek bakımı, büyüme, adet ve gebelik kayıtları cihazın güvenli deposunda şifrelenir.': 'Les données de soins, de croissance, de règles et de grossesse sont chiffrées dans le stockage sécurisé de l\'appareil.',
  'Bebek bakımı, gebelik, yemek planlama veya uygulamanın kullanımı hakkında genel bir soru sorabilirsiniz.': 'Vous pouvez poser une question générale sur les soins du bébé, la grossesse, la planification des repas ou l\'utilisation de l\'application.',
