  'Bebek gelince çift ilişkisi de değişir; açık iletişim ve adil iş bölümü yükü hafifletir.': 'L\'arrivée d\'un bébé change aussi le couple ; une communication ouverte et un partage équitable des tâches allègent la charge.',
