  'Bebek hareketlerinde belirgin azalma veya durma: hemen başvur.': 'Nette diminution ou arrêt des mouvements du bébé : consultez immédiatement.',
  'Bebek hareketlerinde belirgin azalma, kanama, su gelmesi, düzenli kasılmalar, şiddetli baş ağrısı veya görme bozukluğu: aynı gün başvur. Acil durumda 112.': 'Nette diminution des mouvements, saignement, perte de liquide, contractions régulières, maux de tête intenses ou troubles visuels : consultez le jour même. En cas d\'urgence, appelez le numéro d\'urgence local.',
