  'Bebek hızla büyüdüğü için kıyafet ve ekipmanlar kısa süre kullanılır.': 'Les bébés grandissent vite, les vêtements et équipements servent peu de temps.',
  'Bebek hızla kilo alır; doğuma hazırlık ve bebek hareketlerinin takibi önem kazanır.': 'Votre bébé prend du poids rapidement ; la préparation à l\'accouchement et le suivi des mouvements deviennent importants.',
