  'Bebek: {0}': 'Bébé : {0}',
  'Bebekle konuş, ninni söyle, yüz ifadelerine karşılık ver.': 'Parlez à votre bébé, chantez des berceuses, répondez à ses expressions.',
  'Bebekle seyahat': 'Voyager avec un bébé',
  'Bebekler her gün yıkanmak zorunda değildir; haftada 2–3 banyo çoğu bebek için yeterlidir.': 'Un bain quotidien n\'est pas nécessaire ; 2–3 bains par semaine suffisent pour la plupart des bébés.',
  'Bebekler mümkün olduğunca uzun süre (en az 15 ay ve üreticinin sınırlarına kadar) arkaya bakan koltukta taşınmalıdır.': 'Les bébés doivent voyager dos à la route le plus longtemps possible (au moins 15 mois et jusqu\'aux limites du fabricant).',
  'Bebekler yılda birçok kez soğuk algınlığı geçirebilir; nefes alma şekli en önemli takip noktasıdır.': 'Les bébés peuvent attraper de nombreux rhumes par an ; le plus important est de surveiller leur respiration.',
  'Bebekler, gebeler ve yaşlılar gıda zehirlenmesine daha duyarlıdır.': 'Les bébés, les femmes enceintes et les personnes âgées sont plus vulnérables aux intoxications alimentaires.',
  'Bebeklerde ateş': 'La fièvre chez le bébé',
  'Bebeklerde demir desteğini hekim önerisine göre sürdür.': 'Poursuivez la supplémentation en fer du bébé selon l\'avis du médecin.',
  'Bebeklerde her yanık, yüz-el-genital bölge yanıkları, avuç içinden büyük yanıklar.': 'Toute brûlure chez un bébé, brûlure au visage, aux mains ou aux organes génitaux, brûlure plus grande que la paume.',
  'Bebeklerde ishal ve kusmanın en önemli riski sıvı kaybıdır (dehidratasyon).': 'Le plus grand risque de la diarrhée et des vomissements chez le bébé est la perte de liquide (déshydratation).',
  'Bebeklerde kabızlık': 'Constipation chez le bébé',
  'Bebeklerde uyku düzeni': 'Le sommeil chez le bébé',
  'Bebeklerimde ara...': 'Rechercher mes bébés...',
  'Bebeklerin yarısından fazlasında görülür; çoğu 12. aya kadar kendiliğinden geçer.': 'Cela concerne plus de la moitié des bébés ; la plupart en sont sortis vers 12 mois.',
  'Bebekli ev düzeni ve zaman yönetimi': 'Organisation de la maison et gestion du temps avec un bébé',
  'Bebekli yaşamın ilk yılı yeni harcamalar getirir; planlamak stresi azaltır.': 'La première année avec un bébé apporte de nouvelles dépenses ; planifier réduit le stress.',
  'Bebekte her beslenme sonrası belirgin rahatsızlık, kanlı dışkı veya döküntü varsa (nadiren besin alerjisi).': 'Si votre bébé montre un inconfort marqué après chaque tétée, des selles sanglantes ou une éruption (rarement une allergie alimentaire).',
  'Bebeğe bakamama veya bağ kuramama hissi.': 'Sentiment de ne pas pouvoir vous occuper de votre bébé ou créer un lien avec lui.',
  'Bebeğe bakımda yaşına uygun küçük görevler ver.': 'Confiez-lui de petites tâches adaptées à son âge pour s\'occuper du bébé.',
  'Bebeği asla sarsma: sarsılmış bebek sendromu kalıcı beyin hasarına yol açabilir.': 'Ne secouez jamais un bébé : le syndrome du bébé secoué peut causer des lésions cérébrales permanentes.',
  'Bebeği biberonla uyutma; şekerli içecek verme.': 'Ne couchez pas votre bébé avec un biberon ; ne donnez pas de boissons sucrées.',
  'Bebeği değiştirme masası, yatak veya kanepe üzerinde bir an bile yalnız bırakmamak düşmeleri önler.': 'Ne jamais laisser votre bébé seul, même un instant, sur une table à langer, un lit ou un canapé évite les chutes.',
  'Bebeği gün ışığında doğrudan güneşe çıkarmak tedavi yerine geçmez.': 'Exposer votre bébé au soleil direct ne remplace pas un traitement.',
  'Bebeği her uykuda başının farklı tarafına bakacak şekilde yatır (yine sırtüstü).': 'Alternez le côté vers lequel la tête est tournée à chaque sommeil (toujours sur le dos).',
  'Bebeği ince giydir, odayı serin tut, sık sık emzir veya sıvı ver.': 'Habillez légèrement votre bébé, gardez la pièce fraîche et allaitez ou donnez à boire souvent.',
  'Bebeği memeden ayırırken parmağınla vakumu kes.': 'Rompez la succion avec le doigt avant de retirer votre bébé du sein.',
  'Bebeği suda asla yalnız bırakmayın.': 'Ne laissez jamais le bébé seul dans l\'eau.',
  'Bebeği sırtüstü, düz ve sert bir uyku yüzeyine yatırın; uyku alanında gevşek yastık ve örtü bulundurmayın.': 'Couchez votre bébé sur le dos sur une surface plane et ferme ; tenez oreillers et couvertures lâches hors du lit.',
  'Bebeği uykulu ama uyanıkken yatağa koymayı dene.': 'Essayez de coucher votre bébé somnolent mais encore éveillé.',
  'Bebeği yüksek yüzeylerde bir an bile yalnız bırakma; sarsma. Arkaya bakan oto koltuğu kullan. 3 aydan küçük bebekte ateş acil değerlendirme gerektirir.': 'Ne laissez jamais votre bébé seul sur une surface en hauteur, même un instant ; ne le secouez pas. Utilisez un siège auto dos à la route. La fièvre chez un bébé de moins de 3 mois doit être évaluée en urgence.',
