  'Beslenme saatlerini ve miktarları takip ederek kendi kayıtlarınızı karşılaştırabilirsiniz. Yaşa uygun beslenme için sağlık uzmanınıza danışın.': 'En suivant les heures et les quantités des repas, vous pouvez comparer vos propres données. Demandez à votre professionnel de santé quelle alimentation convient à l\'âge.',
  'Beslenme sonrası az miktarda süt çıkarmak ilk aylarda çok yaygındır ve genellikle zararsızdır.': 'Rejeter de petites quantités de lait après la tétée est très fréquent les premiers mois et généralement sans gravité.',
