  'Beyaz fasulyenin üçte ikisini ve sıcak suyu ekleyin; kaynayınca kısık ateşte kapağı kapalı 15 dakika, kabaklar iyice yumuşayana kadar pişirin.': 'Ajoutez les deux tiers des haricots et l’eau chaude ; à ébullition, faites cuire à couvert à feu doux 15 minutes jusqu’à ce que les courgettes soient bien tendres.',
