  'Bez değişimi sonrası ellerini iyice yıka.': 'Lavez-vous bien les mains après le change.',
  'Bez değiştirme ve beslenme malzemelerini evde 1–2 noktada topla.': 'Regroupez le matériel de change et de repas à 1–2 endroits de la maison.',
