  'Bez ıslatmama, ağız kuruluğu, gözyaşı olmadan ağlama (susuzluk).': 'Pas de couche mouillée, bouche sèche, pleurs sans larmes (déshydratation).',
  'Bez, cilt ve beslenme kayıtlarını izleyin. Kontrolleri sağlık ekibinizle planlayın; ateş veya beslenme güçlüğünde yaşa uygun acil değerlendirme gereksinimini sorun.': 'Tenez à jour couches, peau et alimentation. Planifiez les contrôles avec votre équipe de santé ; renseignez-vous sur l\'urgence selon l\'âge en cas de fièvre ou de difficultés alimentaires.',
