  'Doğum': 'Naissance',
  'Doğum Sonrası': 'Après la naissance',
  'Doğum Sonrası & Annelik': 'Après la naissance & maternité',
  'Doğum ağrısıyla baş etmek için ilaçsız ve ilaçlı birçok yöntem vardır.': 'Il existe de nombreux moyens, médicamenteux ou non, pour faire face à la douleur de l\'accouchement.',
  'Doğum başlamazsa doktorunun izlem planını öğren; genellikle 41. haftada değerlendirme yapılır.': 'Si le travail ne commence pas, renseignez-vous sur le plan de surveillance de votre médecin ; une évaluation a généralement lieu à 41 semaines.',
  'Doğum başlangıcı belirtileri': 'Signes du début du travail',
  'Doğum bekleniyor': 'Naissance prévue',
  'Doğum belirtilerini ve ne zaman hastaneye gideceğini gözden geçir.': 'Révisez les signes du travail et quand partir à la maternité.',
  'Doğum günleri': 'Anniversaires',
  'Doğum hazırlık eğitimleri bilinmezliği azaltabilir.': 'Les cours de préparation peuvent réduire l\'incertitude.',
  'Doğum hazırlık eğitimleri nefes ve gevşeme tekniklerini öğrenmeye yardımcı olur.': 'Les cours de préparation aident à apprendre les techniques de respiration et de relaxation.',
  'Doğum hazırlık sınıflarına katılmayı düşün.': 'Pensez à suivre des cours de préparation à la naissance.',
  'Doğum hazırlık sınıflarını araştır.': 'Renseignez-vous sur les cours de préparation à la naissance.',
  'Doğum izni ve çalışan anne hakları': 'Congé maternité et droits des mères qui travaillent',
  'Doğum kasılmalarının süresi ve aralığı': 'Durée et fréquence des contractions',
  'Doğum planı': 'Projet de naissance',
  'Doğum planı esnek olmalıdır; tıbbi durum değişebilir.': 'Un projet de naissance doit rester souple ; la situation médicale peut changer.',
  'Doğum planı ve hazırlık': 'Projet de naissance et préparation',
  'Doğum planı, doğumla ilgili tercihlerini ekiple paylaşmanı kolaylaştıran kısa bir nottur.': 'Le projet de naissance est une note courte qui aide à partager vos souhaits avec l\'équipe.',
  'Doğum referansı eksik': 'La référence de naissance est manquante',
  'Doğum sonrası': 'Après la naissance',
  'Doğum sonrası bakım': 'Soins postnatals',
  'Doğum sonrası bakım ekranları': 'Écrans des soins postnatals',
  'Doğum sonrası depresyon her 7–10 anneden birinde görülür ve tedavi edilebilir.': 'La dépression post-partum touche 1 mère sur 7 à 10 et se soigne.',
  'Doğum sonrası destek': 'Soutien postnatal',
  'Doğum sonrası dikişler genellikle birkaç haftada iyileşir; temizlik ve dinlenme iyileşmeyi destekler.': 'Les points après l\'accouchement cicatrisent généralement en quelques semaines ; l\'hygiène et le repos favorisent la guérison.',
  'Doğum sonrası doğum kontrolü': 'Contraception après l\'accouchement',
  'Doğum sonrası duygusal dalgalanmalar görülebilir. Yoğun üzüntü, kaygı veya işlev kaybı sürüyorsa profesyonel destek alın. Kendinize veya bebeğe zarar verme düşüncesinde acil yardım isteyin.': 'Les hauts et les bas émotionnels sont fréquents après la naissance. Demandez un soutien professionnel si une tristesse intense, de l\'anxiété ou des difficultés à fonctionner persistent. Demandez une aide d\'urgence si vous avez des pensées de vous faire du mal ou de faire du mal à votre bébé.',
  'Doğum sonrası günlük': 'Journal postnatal',
  'Doğum sonrası hüzün ve depresyon': 'Baby blues et dépression post-partum',
  'Doğum sonrası idrar kaçırma yaygındır ve çoğu zaman tedavi edilebilir.': 'Les fuites urinaires après l\'accouchement sont fréquentes et souvent traitables.',
  'Doğum sonrası ilk saat: ten tene temas': 'La première heure après la naissance : le peau à peau',
  'Doğum sonrası kontrol genellikle 6. haftada yapılır; daha erken kontroller de önerilebilir.': 'La visite postnatale a généralement lieu à 6 semaines ; des contrôles plus précoces peuvent être recommandés.',
  'Doğum sonrası kontrol randevumu planladım': 'J\'ai planifié ma visite postnatale',
  'Doğum sonrası kontrolde yöntem seçeneklerini hekiminle konuş.': 'Discutez des options avec votre médecin lors de la visite postnatale.',
  'Doğum sonrası kontrolleri sağlık ekibinizle planlayın. Kanama, ağrı, ilaçlar, korunma ve emzirme ile ilgili sorularınızı not edin.': 'Planifiez les contrôles postnatals avec votre équipe soignante. Notez vos questions sur les saignements, la douleur, les médicaments, la contraception et l\'allaitement.',
  'Doğum sonrası korse': 'Ceinture post-partum',
  'Doğum sonrası ve annelik': 'Après la naissance et maternité',
  'Doğum sonrası yaklaşık {0}. gün • {1}. hafta': 'Environ {0}e jour après la naissance • semaine {1}',
  'Doğum sırasında ihtiyaçlarını ekibe açıkça söyle.': 'Dites clairement à l\'équipe ce dont vous avez besoin pendant le travail.',
  'Doğum tarihi': 'Date de naissance',
  'Doğum tarihi eklenmedi': 'Aucune date de naissance ajoutée',
  'Doğum tarihi gelecekte olamaz.': 'La date de naissance ne peut pas être dans le futur.',
  'Doğum tarihi girildiğinde bebeğin ayına göre açılır': 'S\'ouvre selon l\'âge de votre bébé une fois la date de naissance saisie',
  'Doğum tarihi girilmedi: tüm yaş grupları gösteriliyor.': 'Aucune date de naissance saisie : toutes les tranches d\'âge sont affichées.',
  'Doğum tarihi seç': 'Choisir la date de naissance',
  'Doğum tarihi seçilmelidir.': 'Une date de naissance doit être sélectionnée.',
  'Doğum tarihi: {0}': 'Date de naissance : {0}',
  'Doğum tarihi: {0}.{1}.{2}': 'Date de naissance : {0}.{1}.{2}',
  'Doğum tarihim (yaşa uygun kontroller için)': 'Ma date de naissance (pour les contrôles adaptés à l\'âge)',
  'Doğum tarihim: {0}': 'Ma date de naissance : {0}',
  'Doğum tarihinden önceki kayıt': 'Donnée antérieure à la date de naissance',
  'Doğum tarihini düzenle': 'Modifier la date de naissance',
  'Doğum tarihini seç': 'Choisir la date de naissance',
  'Doğum tarihini “Anne profilim”e girersen yaşına uygun kontroller gösterilir.': 'Si vous saisissez votre date de naissance dans « Mon profil », les contrôles adaptés à votre âge s\'affichent.',
  'Doğum tercihlerini (doğum planı) yazmaya başla.': 'Commencez à écrire vos souhaits pour l\'accouchement (projet de naissance).',
  'Doğum tercihlerini ve sorularını önceden hekiminle konuş.': 'Discutez à l\'avance de vos souhaits et questions avec votre médecin.',
  'Doğum yapacağın hastanenin acil iletişim bilgilerini telefonuna kaydet.': 'Enregistrez dans votre téléphone les coordonnées d\'urgence de la maternité.',
  'Doğum yapacağın hastaneyi ve ulaşımı netleştir.': 'Confirmez la maternité et la façon de vous y rendre.',
  'Doğum yeri, ulaşım ve destek kişini planla.': 'Prévoyez le lieu d\'accouchement, le transport et votre accompagnant.',
  'Doğum çantasını hazırla': 'Préparez votre valise de maternité',
  'Doğum şekli anne ve bebeğin durumuna göre hekimle birlikte planlanır.': 'Le mode d\'accouchement est planifié avec votre médecin selon votre état et celui de votre bébé.',
  'Doğum şekline göre iyileşme farklılık gösterir. Ağrı, kanama, yara bakımı ve hareket konusunda taburculuk önerilerini takip edin. Dinlenme için yakınlarınızdan destek isteyin.': 'La récupération varie selon le type d\'accouchement. Suivez les conseils de sortie sur la douleur, les saignements, les soins de la plaie et la mobilité. Demandez du soutien à vos proches pour pouvoir vous reposer.',
  'Doğum, nüfus müdürlüğüne yasal süre içinde bildirilmelidir; hastanelerde çoğu zaman doğum bildirimi elektronik yapılır.': 'La naissance doit être déclarée dans le délai légal ; les maternités la transmettent souvent électroniquement.',
  'Doğum: {0}': 'Naissance : {0}',
  'Doğum: {0}.{1}.{2}': 'Naissance : {0}.{1}.{2}',
  'Doğuma hazırlık listesi': 'Liste de préparation à l\'accouchement',
  'Doğuma yakın dönem: doğum belirtileri ve başvuru planını sağlık ekibinle netleştir.': 'Près du terme : clarifiez avec votre équipe soignante les signes du travail et le moment de partir à la maternité.',
  'Doğumda ağrı yönetimi': 'Soulager la douleur de l\'accouchement',
  'Doğumdan aylar sonra süren idrar veya gaz kaçırma.': 'Fuites d\'urine ou de gaz qui persistent des mois après l\'accouchement.',
  'Doğumdan hemen sonra ten tene temas ve ilk saatte emzirme anne ve bebeğe birçok fayda sağlar.': 'Le peau à peau juste après la naissance et la mise au sein dans la première heure apportent de nombreux bienfaits à la mère et au bébé.',
  'Doğumdan sonra işe dönüş hem duygusal hem pratik bir geçiştir; önceden planlamak kolaylaştırır.': 'Reprendre le travail après une naissance est une transition à la fois émotionnelle et pratique ; anticiper aide.',
  'Doğumdan sonra nüfus kaydı ve sağlık güvencesi işlemlerinin zamanında yapılması gerekir.': 'Après la naissance, l\'état civil et l\'assurance santé doivent être réglés dans les délais.',
  'Doğumdan sonraki ilk 6 hafta vücudun toparlandığı, dinlenme ve desteğin en çok gerektiği dönemdir.': 'Les 6 premières semaines après la naissance sont celles où votre corps récupère et où vous avez le plus besoin de repos et de soutien.',
  'Doğumdan sonraki ilk adet gelmeden de gebelik oluşabilir.': 'Vous pouvez tomber enceinte avant même vos premières règles après l\'accouchement.',
  'Doğumdan sonraki ilk günlerde hüzün yaygındır; iki haftadan uzun süren belirtiler depresyon olabilir.': 'Se sentir déprimée les premiers jours après l\'accouchement est fréquent ; des symptômes de plus de deux semaines peuvent être une dépression.',
  'Doğumdan sonraki ilk günlerde topuk kanı ve işitme taraması yapılır; 3–5. günde ilk kontrol önerilir.': 'Les premiers jours après la naissance, les dépistages au talon et auditif sont réalisés ; un premier contrôle est recommandé entre le 3e et le 5e jour.',
  'Doğumdan sonraki ilk hafta içinde topuk kanı taraması ve işitme taraması yapılır.': 'Un dépistage par prélèvement au talon et un dépistage auditif sont réalisés la première semaine après la naissance.',
  'Doğumdan sonraki ilk kontrolü (genellikle 3–5. gün) aksatma.': 'Ne manquez pas le premier contrôle après la naissance (généralement entre le 3e et le 5e jour).',
  'Doğumdan sonraki kontrolleri aksatma.': 'Ne manquez pas les contrôles après la naissance.',
  'Doğu’nun hanı': 'Khan de l’Orient',
  'Dudak kremi': 'Baume à lèvres',
  'Dudak veya yüzde morarma, nefes durmaları: 112.': 'Lèvres ou visage bleus, pauses respiratoires : appelez le numéro d\'urgence local.',
  'Dudak/dil şişmesi, nefes darlığı, hırıltı, yaygın kurdeşen, bilinç değişikliği: 112.': 'Gonflement des lèvres/de la langue, essoufflement, sifflement, urticaire généralisée, altération de la conscience : appelez le numéro d\'urgence local.',
