  'Duvara düşen gölgeleri birlikte inceleyin.': 'Observez ensemble les ombres sur le mur.',
  'Duygu aynası': 'Miroir des émotions',
  'Duygu kartları': 'Cartes des émotions',
  'Duygu ve rutinler': 'Émotions et routines',
  'Duyguları adlandırma': 'Nommer ses émotions',
  'Duyguları adlandırma ("kızgın mısın?"), rol oyunları, açık havada tırmanma (alçak ve güvenli).': 'Nommer les émotions (« tu es en colère ? »), jeux de rôle, grimper dehors (bas et sûr).',
  'Duyguları adlandırmasına yardım et ("kızgın görünüyorsun").': 'Aidez-le à nommer ses émotions (« tu as l\'air en colère »).',
  'Duygularını güvendiğin biriyle paylaş; yardım istemek güçlü bir adımdır.': 'Confiez vos émotions à une personne de confiance ; demander de l\'aide est une démarche forte.',
  'Duygularını paylaşabileceğin kişilerle konuş.': 'Parlez à des personnes à qui vous pouvez confier vos émotions.',
  'Duyu': 'Sens',
  'Duyular gelişir; dokunmayı hissedebilir, kaşları belirir.': 'Les sens se développent ; votre bébé ressent le toucher et les sourcils apparaissent.',
  'Duyusal algı gelişir; hızla kilo alır.': 'La perception sensorielle se développe ; votre bébé prend du poids rapidement.',
  'Döküntü, dudak/dil şişmesi, kusma veya nefes darlığı: alerji, acil olabilir.': 'Éruption, gonflement des lèvres/de la langue, vomissements ou essoufflement : allergie, possible urgence.',
  'Döllenmiş yumurta (zigot) hızla bölünerek rahme doğru ilerler.': 'L\'œuf fécondé (zygote) se divise rapidement en avançant vers l\'utérus.',
  'Döngü Takibi': 'Suivi du cycle',
  'Döngü değişimi, cilt ve diğer belirtileri hekiminizle görüşmek için not edin.': 'Notez les changements de cycle, de peau et les autres symptômes à aborder avec votre médecin.',
  'Döngü kayıtları': 'Données du cycle',
  'Döngü süresi: ortalama {0} gün ({1} kayıttan)': 'Durée du cycle : moyenne {0} jours (sur {1} saisies)',
  'Döngü süresi: {0} gün (varsayılan; daha fazla kayıt girince ölçülür)': 'Durée du cycle : {0} jours (par défaut ; mesurée quand vous aurez saisi plus de données)',
  'Döngü uzunluğu (gün)': 'Durée du cycle (jours)',
  'Döngü ve belirtiler': 'Cycle et symptômes',
  'Döngü • Sağlık': 'Cycle • Santé',
  'Döngü, gebelik, doğum sonrası ve belirtiler': 'Cycle, grossesse, post-partum et symptômes',
  'Döngü, gebelik, doğum sonrası ve kontrol notları': 'Cycle, grossesse, post-partum et notes de contrôle',
  'Döngü, gebelik, doğum sonrası ve menopoz notları': 'Cycle, grossesse, post-partum et notes de ménopause',
  'Döngünün sürekli 21 günden kısa veya 35 günden uzun olması.': 'Cycles régulièrement plus courts que 21 jours ou plus longs que 35 jours.',
  'Dönüşten 2–3 hafta önce bakım düzenini denemeye başla.': 'Commencez à tester le mode de garde 2–3 semaines avant la reprise.',
  'Dördüncü; ilkbahar': 'Quatrième ; printemps',
  'Dün, ': 'Hier, ',
  'Dünya': 'Le monde',
  'Dünya mutfağı': 'Cuisine du monde',
  'Dünyaya önem vermeyen, sofu': 'Détaché du monde, ascète',
  'Dünyayı fetheden': 'Conquérant du monde',
  'Dürüst han': 'Khan honnête',
  'Düzenle': 'Modifier',
  'Düzenleyen; şair': 'Celui qui ordonne ; poète',
  'Düzenli ana ve ara öğün fırsatları sunun; açlık-tokluk işaretlerine saygı gösterin. Üzüm, sert kuruyemiş ve benzeri boğulma risklerini uygun şekilde hazırlayın.': 'Proposez des repas et collations réguliers ; respectez les signaux de faim et de satiété. Préparez de façon adaptée les raisins, fruits à coque durs et autres aliments à risque d\'étouffement.',
  'Düzenli egzersiz ve dengeli beslenme belirtileri azaltabilir.': 'L\'activité régulière et une alimentation équilibrée peuvent réduire les symptômes.',
  'Düzenli egzersiz, kalsiyum ve D vitamini açısından zengin beslenme.': 'Activité régulière et alimentation riche en calcium et en vitamine D.',
  'Düzenli egzersiz, yeterli uyku, tuz ve kafeini azaltmak yardımcı olabilir.': 'Une activité régulière, un sommeil suffisant et moins de sel et de caféine peuvent aider.',
  'Düzenli harcamaları ve yaklaşan ihtiyaçları yazın. Alışveriş öncesinde evdeki stokları kontrol edin.': 'Notez les dépenses régulières et les besoins à venir. Vérifiez ce que vous avez avant de faire les courses.',
  'Düzenli hareket, uyku ve dengeli beslenme duygudurumu destekler.': 'Activité régulière, sommeil et alimentation équilibrée soutiennent l\'humeur.',
  'Düzenli kontrol et; çatlak veya yıpranmışsa değiştir.': 'Vérifiez-la régulièrement ; remplacez-la si elle est fendue ou usée.',
  'Düzenli kontrol planı': 'Plan de suivi régulier',
  'Düzenli kullandığım ilaçlar': 'Médicaments que je prends régulièrement',
  'Düzenli uyku ve uyanma saatlerini not edin; çocuğun ihtiyaçlarına göre rutini uyarlayın.': 'Notez les horaires réguliers de sommeil et d\'éveil ; adaptez la routine aux besoins de votre enfant.',
  'Düzenli ve giderek sıklaşan kasılmalar, su gelmesi ve nişan gelmesi doğumun başladığını gösterebilir.': 'Des contractions régulières et rapprochées, la rupture de la poche des eaux et la perte du bouchon muqueux peuvent signaler le début du travail.',
  'Düzenli yürüyüş gibi bir egzersiz rutini oluştur.': 'Mettez en place une routine d\'activité comme des marches régulières.',
  'Düzenli, hafif-orta egzersiz (yürüyüş, yüzme, gebe yogası) faydalıdır.': 'Une activité régulière légère à modérée (marche, natation, yoga prénatal) est bénéfique.',
  'Düzensiz adet, androjen fazlalığı belirtileri ve yumurtalıklarda çok sayıda küçük folikülle seyreden yaygın bir hormonal durumdur.': 'Un trouble hormonal fréquent associant règles irrégulières, signes d\'excès d\'androgènes et nombreux petits follicules dans les ovaires.',
  'Düzensiz adet, kronik hastalık veya önceki gebelik kayıpları varsa erkenden.': 'Tôt, en cas de règles irrégulières, de maladie chronique ou de fausses couches antérieures.',
  'Düzensiz ve düzenli kasılmaları ayırt etmeye çalış.': 'Essayez de distinguer contractions irrégulières et régulières.',
  'Düzensiz veya hiç adet görmeme, bilinen tüp veya rahim sorunu.': 'Règles irrégulières ou absentes, problème connu des trompes ou de l\'utérus.',
  'Düzensiz veya seyrek adet, sivilce, tüylenme ve kilo artışı görülebilir.': 'Règles irrégulières ou espacées, acné, pilosité excessive et prise de poids peuvent apparaître.',
  'Düzleşme 4 aydan sonra artıyorsa veya alın/kulaklarda asimetri varsa.': 'Si l\'aplatissement augmente après 4 mois ou si le front/les oreilles sont asymétriques.',
  'Düğme pil veya mıknatıs yutma şüphesi: hemen acil servis.': 'Suspicion d\'ingestion d\'une pile bouton ou d\'un aimant : allez immédiatement aux urgences.',
  'Düğme pilleri ve mıknatısları çocuklardan uzak tut.': 'Tenez les piles bouton et les aimants hors de portée des enfants.',
  'Düş': 'Rêve',
  'Düşme sonrası diş kırığı veya yerinden çıkma: hemen diş hekimi.': 'Dent cassée ou expulsée après une chute : consultez un dentiste immédiatement.',
  'Düşme ve darbe riski olan sporlar ile sırtüstü uzun süre yatmayı gerektiren hareketler önerilmez.': 'Les sports avec risque de chute ou de choc et les exercices longs allongée sur le dos ne sont pas recommandés.',
  'Düşme ve kafa travması': 'Chutes et traumatismes crâniens',
  'Düşmeler, zehirlenmeler, yanıklar ve boğulma en sık ev kazalarıdır.': 'Chutes, intoxications, brûlures et noyades sont les accidents domestiques les plus fréquents.',
  'Düştükten sonra birkaç gün az miktarda kanlı lekelenme olabilir.': 'Après sa chute, un léger saignement pendant quelques jours est possible.',
  'Düşük ışıklı gece aydınlatması.': 'Éclairage de nuit tamisé.',
  'Düşüklerin çoğu ilk 12 haftada ve genellikle kromozom farklılıklarına bağlı olarak gerçekleşir.': 'La plupart des fausses couches surviennent dans les 12 premières semaines, généralement dues à des anomalies chromosomiques.',
  'Düşünce': 'Pensée',
  'DİKKAT: Yedekte bulunan alanlardaki mevcut kayıtlar yedekteki değerlerle değiştirilecek. Yedekte olmayan alanlardaki kayıtlar korunur. İşlem öncesi yine de mevcut verilerinizi ayrıca yedekleyin.': 'ATTENTION : les données existantes des domaines inclus dans la sauvegarde seront remplacées par celles de la sauvegarde. Les données des domaines absents de la sauvegarde sont conservées. Sauvegardez quand même vos données actuelles séparément avant de continuer.',
  'DİKKAT: Çocuk 49–72 aylık yakalama aşılaması yaş grubunda olabilir. İkinci suçiçeği dozu için aile hekiminizle görüşün. Bu uyarı aşı yapılmadığı anlamına gelmez.': 'REMARQUE : l\'enfant peut faire partie du groupe de rattrapage vaccinal de 49 à 72 mois. Parlez de la deuxième dose contre la varicelle avec votre médecin traitant. Cet avertissement ne signifie pas que le vaccin n\'a pas été fait.',
  'Dışarı çıkarken malzeme taşıma.': 'Pour emporter ses affaires en sortie.',
  'E-posta adresi': 'Adresse e-mail',
  'E-posta adresi kayıtlıysa şifre sıfırlama bağlantısı gönderilir.': 'Si l\'adresse e-mail est enregistrée, un lien de réinitialisation du mot de passe sera envoyé.',
  'E-posta doğrulaması gerekebilir.': 'Une vérification de l\'e-mail peut être nécessaire.',
  'Ebedi, ölümsüz': 'Éternel, immortel',
  'Ebedi; Allah’ın adlarından': 'Éternel ; un des noms de Dieu',
  'Ebeveyn tükenmişliği': 'Épuisement parental',
  'Ebeveynlerle soru sor, deneyim paylaş; moderasyonlu ve güvenli topluluk.': 'Posez des questions aux parents et partagez vos expériences ; une communauté modérée et sûre.',
  'Eczacına gebe olduğunu mutlaka söyle.': 'Dites toujours à votre pharmacien que vous êtes enceinte.',
