  'Ek gıda': 'Diversification',
  'Ek gıda döneminde uygun doku, hijyen ve alerjenleri göz önünde bulundurun. Boğulma riski taşıyan yiyeceklerden kaçının.': 'Pendant la diversification, pensez aux textures adaptées, à l\'hygiène et aux allergènes. Évitez les aliments qui présentent un risque d\'étouffement.',
  'Ek gıda: {0} kayıt': 'Diversification : {0} saisies',
