  'Ek gıdaya geçiş': 'Début de la diversification',
  'Ek gıdaya geçişte kabızlık sıklaşabilir.': 'La constipation peut devenir plus fréquente au début de la diversification.',
  'Ek gıdaya geçtiyse su ve lifli besinler (erik, armut, sebze püreleri) ver.': 'Si votre bébé est diversifié, donnez de l\'eau et des aliments riches en fibres (prunes, poires, purées de légumes).',
  'Ek gıdaya hazırlık belirtilerini ve yeni besinleri not edin. Boğulma riskini azaltan uygun kıvam ve güvenli oturma önemlidir.': 'Notez les signes de maturité pour la diversification et les nouveaux aliments. Une texture qui limite le risque d\'étouffement et une position assise sûre sont importantes.',
  'Ek gıdaya küçük miktarlarla başlayın. Demir içeren besinlere, farklı tatlara ve uygun dokulara yer verin. Anne sütü veya formül sürer.': 'Commencez la diversification en petites quantités. Incluez des aliments riches en fer, des goûts variés et des textures adaptées. Le lait maternel ou infantile continue.',
