  'Günlük bakımda geniş spektrumlu SPF 30 veya üzeri güneş koruyucu kullanın. Açık havada ürünün etiketine göre yenileyin; gölge ve şapka gibi fiziksel önlemleri ekleyin.': 'Utilisez au quotidien une protection solaire à large spectre SPF 30 ou plus. Renouvelez dehors selon l\'étiquette ; ajoutez ombre et chapeau.',
