  'Hazır olma belirtileri varsa ek gıdaya başla: tek tek, birkaç gün arayla, püre kıvamında. Demirden zengin besinler (et, yumurta sarısı, mercimek) öncelikli. Tuz, şeker ve bal eklenmez; anne sütü devam eder.': 'S\'il y a des signes de maturité, commencez la diversification : un aliment à la fois, à quelques jours d\'intervalle, en purée. Les aliments riches en fer (viande, jaune d\'œuf, lentilles) d\'abord. Pas de sel, sucre ni miel ; l\'allaitement continue.',
