  'Her ay için gelişim, beslenme, uyku, oyun, bakım ve güvenlik. İçerikler genel öneridir; aylık gelişim kontrol listesi değildir.': 'Développement, alimentation, sommeil, jeu, soins et sécurité pour chaque mois. Le contenu est un conseil général ; ce n\'est pas une liste de contrôle mensuelle du développement.',
