  'Kahvaltı, öğle ve akşam için tarif önerileri': 'Idées de recettes pour le petit-déjeuner, le déjeuner et le dîner',
  'Kahvaltı, öğle ve akşam için tarif önerileri oluşturulur. Beslenme veya sağlık önerisi değildir.': 'Les idées de recettes sont créées pour le petit-déjeuner, le déjeuner et le dîner. Ce ne sont pas des conseils nutritionnels ou de santé.',
