  'Kaka sıklığı bebekten bebeğe çok değişir; sert ve zor çıkan dışkı kabızlığı düşündürür.': 'La fréquence des selles varie beaucoup ; des selles dures et difficiles à émettre évoquent une constipation.',
  'Kaka yaparken kızarma ve ıkınma tek başına kabızlık değildir.': 'Rougir et pousser pour faire ses selles n\'est pas en soi une constipation.',
  'Kakaolu puding': 'Crème au cacao',
  'Kalan bütün fasulyeleri ekleyin, tuz ve karabiberle tatlandırıp 3 dakika daha kaynatın; kıvam koyuysa biraz sıcak su ekleyin.': 'Ajoutez le reste des haricots entiers, salez, poivrez et laissez mijoter 3 minutes ; ajoutez un peu d’eau chaude si c’est trop épais.',
  'Kalan bütün nohutları ekleyin; tuz, kimyon ve gerekiyorsa şekerle tatlandırıp 3 dakika daha pişirin.': 'Ajoutez le reste des pois chiches entiers ; assaisonnez de sel, cumin et sucre si besoin et poursuivez 3 minutes.',
  'Kalan suyu tencerede ısıtıp tarhanayı karıştırarak ekleyin.': 'Chauffez le reste de l’eau et ajoutez la tarhana en remuant.',
  'Kalibrasyon': 'Étalonnage',
  'Kaliteli uyku ruh sağlığının temelidir; bebekli dönemde uykuyu korumak için plan yapmak gerekir.': 'Un bon sommeil est la base de la santé mentale ; avec un bébé, il faut un plan pour le protéger.',
  'Kalkınca, yemeklerden sonra ve uyku öncesi lazımlığa oturmayı öner.': 'Proposez le pot au réveil, après les repas et avant de dormir.',
  'Kalp atımı ultrasonda görülebilir; kol ve bacak tomurcukları belirir.': 'Les battements du cœur sont visibles à l\'échographie ; les bourgeons des bras et des jambes apparaissent.',
  'Kalp ve sinir sisteminin temelleri oluşur; nöral tüp kapanmaya başlar.': 'Les bases du cœur et du système nerveux se forment ; le tube neural commence à se fermer.',
