  'Kalsiyum ve D vitamini kemik sağlığının temelidir; gebelik, emzirme ve menopozda önem kazanır.': 'Le calcium et la vitamine D sont la base de la santé osseuse ; ils comptent surtout pendant la grossesse, l\'allaitement et la ménopause.',
  'Kalıba döküp 40 dakika, kürdan temiz çıkana kadar pişirin.': 'Versez dans le moule et enfournez 40 minutes jusqu’à ce qu’un cure-dents ressorte propre.',
