  'Kan şekeri (mg/dL)': 'Glycémie (mg/dL)',
  'Kan şekeri düşük. Hızlı emilen şeker al, 15 dk sonra yeniden ölç; düzelmezse doktoruna başvur.': 'Glycémie basse. Prenez du sucre rapide et mesurez à nouveau après 15 minutes ; si cela ne s\'améliore pas, consultez votre médecin.',
  'Kan şekeri düşük: Hızlı emilen şeker al (ör. yarım bardak meyve suyu), 15 dk sonra yeniden ölç; düzelmezse doktoruna başvur.': 'Glycémie basse : prenez du sucre rapide (ex. un demi-verre de jus de fruits) et mesurez à nouveau après 15 minutes ; si cela ne s\'améliore pas, consultez votre médecin.',
  'Kan şekeri yüksek. Doktorunun önerdiği hedeflere göre değerlendir.': 'Glycémie élevée. Évaluez-la par rapport aux objectifs recommandés par votre médecin.',
  'Kan şekeri yüksek: Doktorunun verdiği hedeflere göre değerlendir ve doktoruna bildir.': 'Glycémie élevée : évaluez-la par rapport aux objectifs fixés par votre médecin et informez-le.',
  'Kan şekeri çok yüksek. Doktoruna hemen başvur.': 'Glycémie très élevée. Consultez immédiatement votre médecin.',
  'Kan şekeri ölçümlerini kaydet; doğumdan sonra kontrol testini yaptır.': 'Notez vos glycémies ; faites le test de contrôle après l\'accouchement.',
  'Kan; nimet': 'Sang ; bienfait',
  'Kanama başlangıcı/bitişi, ağrı ve günlük etkileri not edin. Takvim doğum kontrol yöntemi değildir.': 'Notez le début/la fin des saignements, la douleur et l\'effet sur la journée. Le calendrier n\'est pas une méthode de contraception.',
