  'Kanama, şiddetli veya tek taraflı karın ağrısı, hiçbir şey tutamayacak kadar kusma, ateş: gecikmeden başvur.': 'Saignement, douleur abdominale intense ou d\'un côté, vomissements au point de ne rien garder, fièvre : consultez sans tarder.',
