  'Patates ve ıspanağı fırın kabına kat kat yerleştirin.': 'Alternez pommes de terre et épinards dans un plat.',
  'Patates çorbaya krema eklemeden kadifemsi kıvam verir.': 'La pomme de terre donne une texture veloutée sans ajouter de crème.',
  'Patates, kabak ve biberleri güveç kabına yayın, tuz ve kekik serpin; domatesli sosun yarısını üzerine dökün.': 'Étalez pommes de terre, courgette et poivrons dans la cocotte, salez et parsemez de thym ; versez la moitié de la sauce tomate.',
  'Patatesi küçük küpler halinde doğrayıp tavada yumuşayana kadar pişirin.': 'Coupez la pomme de terre en petits dés et faites-la cuire à la poêle jusqu’à tendreté.',
  'Patatesi çatalla ezip balığa ekleyin; yumurta, soğan, maydanoz, dereotu, tuz, karabiber ve kimyonu ilave edin.': 'Écrasez la pomme de terre à la fourchette et ajoutez-la au poisson ; ajoutez l’œuf, l’oignon, le persil, l’aneth, le sel, le poivre et le cumin.',
  'Patatesler yumuşayana kadar 30 dakika fırınlayın.': 'Enfournez 30 minutes jusqu’à ce que les pommes de terre soient tendres.',
  'Patatesler yumuşayana ve kıyma tamamen pişene dek 35–40 dakika fırınlayın.': 'Enfournez 35–40 minutes jusqu’à ce que les pommes de terre soient tendres et la viande bien cuite.',
  'Patatesleri dilimleyip tavukla fırın kabına yerleştirin.': 'Tranchez les pommes de terre et disposez-les avec le poulet dans un plat.',
