  'Sebze, meyve, protein ve tahıllarda çeşitlilik sağlayın. Çocuğu yemek hazırlığına yaşına uygun görevlerle katın; zorla yedirmekten kaçının.': 'Variez légumes, fruits, protéines et céréales. Impliquez votre enfant dans la préparation avec des tâches adaptées ; évitez de le forcer à manger.',
  'Sebze, meyve, tam tahıl, baklagil ve yeterli protein içeren dengeli öğünler hazırla.': 'Préparez des repas équilibrés avec légumes, fruits, céréales complètes, légumineuses et suffisamment de protéines.',
  'Sebze, meyve, tam tahıl, protein ve süt ürünlerinden çeşitlilik sun. Ne yiyeceğine sen, ne kadar yiyeceğine çocuk karar versin. Şekerli içecekleri ve paketli atıştırmalıkları sınırla.': 'Proposez de la variété : légumes, fruits, céréales complètes, protéines et produits laitiers. Vous décidez de ce qui est mangé ; l\'enfant décide de la quantité. Limitez les boissons sucrées et les en-cas industriels.',
