  'Tansiyon yüksek: Ölçümü 15 dakika dinlenip tekrarla ve aynı gün doktoruna haber ver. Şiddetli baş ağrısı, görme bozukluğu, karın üst kısmında ağrı ya da ani şişlik varsa 112’yi ara.': 'Tension élevée : reposez-vous 15 minutes, mesurez à nouveau et informez votre médecin le jour même. En cas de mal de tête intense, de troubles de la vue, de douleur dans le haut du ventre ou de gonflement soudain, appelez le numéro d\'urgence local.',
