  'Telefon bildirimi isteğe bağlıdır ve izin gerektirir. Pil kısıtlamaları nedeniyle bildirim gecikebilir. Acil sağlık durumları veya ilaç takibi için tek başına kullanılmamalıdır.': 'Les notifications du téléphone sont facultatives et nécessitent une autorisation. Elles peuvent être retardées à cause des restrictions de batterie. Il ne faut pas s\'y fier seules pour les urgences médicales ou le suivi des médicaments.',
