  'Ten tene temas bebeğin ısısını ve kalp atımını düzenler, emzirmeyi başlatmayı kolaylaştırır.': 'Le peau à peau régule la température et le rythme cardiaque du bébé et facilite le début de l\'allaitement.',
  'Ten tene temas, yüz yüze konuşma, ninni. Kısa süreli, uyanıkken gözetimli karın üstü zaman.': 'Peau à peau, parler face à face, berceuses. Courts moments sur le ventre, éveillé et surveillé.',
  'Tencerede kalan yağla soğan ve biberi 4 dakika kavurun, salçayı ekleyip 1 dakika çevirin.': 'Dans une casserole, faites revenir oignon et poivron dans le reste d’huile 4 minutes, ajoutez le concentré et remuez 1 minute.',
  'Tencerede oda sıcaklığına kadar soğutup servis edin.': 'Laissez refroidir à température ambiante dans la casserole et servez.',
