  'Tencerede tereyağını eritip unu 1 dakika kavurun; sütü çırparak ekleyin ve kaynayıp hafif koyulaşana kadar 4 dakika karıştırın.': 'Faites fondre le beurre, ajoutez la farine 1 minute ; versez le lait en fouettant et remuez 4 minutes jusqu’à ébullition et léger épaississement.',
  'Tencerede yağ ile havucu 3 dakika çevirin.': 'Faites revenir la carotte 3 minutes dans l’huile.',
  'Tencerede yağı ısıtıp soğan ve havucu 3 dakika çevirin.': 'Chauffez l’huile et faites revenir oignon et carotte 3 minutes.',
  'Tencerede zeytinyağını ısıtıp soğanı orta ateşte 4 dakika pembeleşene kadar kavurun, sarımsağı ekleyip 30 saniye çevirin.': 'Chauffez l’huile d’olive, faites suer l’oignon 4 minutes à feu moyen, ajoutez l’ail et remuez 30 secondes.',
  'Tencerede zeytinyağıyla doğranmış soğanı 3 dakika kavurun.': 'Faites revenir l’oignon haché à l’huile d’olive 3 minutes.',
