  'Tencerede zeytinyağıyla soğanı 3 dakika kavurun, domatesi ekleyip 4 dakika pişirin.': 'Faites revenir l’oignon à l’huile d’olive 3 minutes, ajoutez la tomate et faites cuire 4 minutes.',
  'Tencerede zeytinyağıyla soğanı 3 dakika kavurun, havucu ekleyip 3 dakika daha çevirin.': 'Faites revenir l’oignon à l’huile d’olive 3 minutes, ajoutez la carotte et poursuivez 3 minutes.',
