  'WHO persentili için doğrulanmış CDC/WHO 0–24 ay CSV dosyaları gereklidir. Üstteki yükleme simgesiyle resmi CSV içeriğini panodan içe aktarabilirsiniz. Referans yüklenmeden persentil hesaplanmaz.': 'Des fichiers CSV CDC/OMS 0–24 mois vérifiés sont nécessaires pour les percentiles OMS. Vous pouvez importer le contenu CSV officiel depuis le presse-papiers avec l\'icône d\'import ci-dessus. Aucun percentile n\'est calculé sans référence.',
