  'Yazdıkların acil değerlendirme gerektirebilecek bir duruma benziyor. Beklemeden 112\'yi ara veya en yakın acil servise başvur. Bu uygulama tanı koymaz ve acil durumda yol gösterici değildir.': 'Ce que vous avez écrit pourrait correspondre à une situation qui nécessite une évaluation urgente. Sans attendre, appelez le numéro d\'urgence local ou rendez-vous aux urgences les plus proches. Cette application ne pose pas de diagnostic et n\'est pas un guide en cas d\'urgence.',
  'Yazdığınız soru gönderilir. E-posta ve telefon numaraları otomatik maskelenir; bu tam anonimleştirme değildir. Ad, adres, tahlil veya başka hassas kişisel bilgi yazmayın.': 'La question que vous écrivez sera envoyée. Les adresses e-mail et numéros de téléphone sont masqués automatiquement ; ce n\'est pas une anonymisation complète. N\'écrivez pas de noms, d\'adresses, de résultats d\'analyses ni d\'autres informations personnelles sensibles.',
