  'Yağla harmanlayıp 200°C fırında yumuşayana kadar pişirin.': 'Mélangez à l’huile et enfournez à 200°C jusqu’à tendreté.',
  'Yağlanmış kalıba döküp ortası tamamen pişene kadar 35-40 dakika fırınlayın.': 'Versez dans un moule graissé et enfournez 35-40 minutes jusqu’à cuisson complète du centre.',
