  'Yerde güvenli bir alanda, oturma ve uzanma becerisine göre yetişkin yardımıyla oynayın.': 'Jouez au sol dans un espace sûr, avec l\'aide d\'un adulte selon ses capacités assis et allongé.',
  'Yerde güvenli bir hareket rotası hazırlayın.': 'Installez au sol un parcours de mouvement sûr.',
