  'Yetişkin kadınlar için günlük toplam sıvı ihtiyacı yaklaşık 2–2,5 litredir; sıcak havada, gebelikte ve emzirmede artar.': 'Une femme adulte a besoin d\'environ 2 à 2,5 litres de liquides par jour au total ; davantage par temps chaud, pendant la grossesse et l\'allaitement.',
  'Yetişkin kontrollü su': 'Eau sous contrôle d\'un adulte',
  'Yetişkin sürekli gözetiminde uygulayın. Küçük parçalar, kopabilen nesneler, ipler ve boğulma riski oluşturan malzemeler kullanmayın. Bebek istemezse durun.': 'À faire sous la surveillance constante d\'un adulte. N\'utilisez ni petites pièces, ni objets qui se détachent, ni ficelles, ni matériaux à risque d\'étouffement. Arrêtez si le bébé ne veut pas.',
