  'Yumurtlama döneminde berrak, kaygan akıntı ve hafif kasık ağrısı olabilir.': 'Autour de l\'ovulation, des pertes claires et filantes et une légère douleur pelvienne sont possibles.',
  'Yumurtlama ve verimli dönem, ortalama döngü süresine göre yaklaşık hesaplanır. Doğum kontrolü veya gebelik planlaması için güvenilir bir yöntem değildir; tıbbi değerlendirme yerine geçmez.': 'L\'ovulation et la période fertile sont estimées à partir de la durée moyenne de votre cycle. Ce n\'est pas une méthode fiable de contraception ou de planification de grossesse et cela ne remplace pas une évaluation médicale.',
  'Yumurtlama çoğunlukla bir sonraki adetten yaklaşık 14 gün önce olur.': 'L\'ovulation survient généralement environ 14 jours avant les règles suivantes.',
