  'Yuvarlanma başladığı için alt değiştirme masasında elini bebekten ayırma. Küçük nesneleri, düğme pilleri ve ipleri ulaşamayacağı yerde tut.': 'Maintenant qu\'il se retourne, gardez une main sur lui sur la table à langer. Gardez petits objets, piles bouton et cordons hors de portée.',
  'Yuvarlanır (çoğunlukla yüzüstüden sırtüstüne); nesneleri ağzına götürür. Adına tepki vermeye başlar, ses tonlarını ayırt eder.': 'Se retourne (souvent du ventre au dos) ; porte les objets à la bouche. Commence à réagir à son prénom, distingue les tons de voix.',
  'Yönetim verilerine erişilemedi. Yönetici yetkinizi, oturumunuzu ve sunucu kurulumunu kontrol edin.': 'Impossible d\'accéder aux données de gestion. Vérifiez l\'autorisation d\'administration, la session et la configuration du serveur.',
