  'Yüklenen referanslar yalnızca bu ekran açıkken tutulur. 0–24 ay aylık WHO persentilleri bilgi amaçlıdır; tıbbi değerlendirme değildir.': 'Les références chargées ne sont conservées que tant que cet écran est ouvert. Les percentiles mensuels OMS 0–24 mois sont informatifs ; ce n\'est pas une évaluation médicale.',
