  'Yüksek sarılık değerleri tedavi edilmezse zarar verebilir; bu nedenle kontrol önemlidir.': 'Un taux de jaunisse très élevé peut être nocif sans traitement, d\'où l\'importance des contrôles.',
  'Yüksek yüzeylerde yalnız bırakmayın. Küçük parçaları, kabloları, ilaçları ve sıcak içecekleri erişimden uzak tutun; uygun oto koltuğu kullanın.': 'Ne le laissez pas seul sur des surfaces en hauteur. Gardez petites pièces, câbles, médicaments et boissons chaudes hors de portée ; utilisez un siège auto adapté.',
