  'Yürüme için güvenli alan, basit şekil yerleştirme, birlikte şarkı ve kitap. 1 yaş kontrolüne git.': 'Un espace sûr pour marcher, encastrements simples, chansons et livres ensemble. Allez au contrôle d\'un an.',
  'Yürüme, ilk kelimeler ve bağımsızlık isteği bu dönemin öne çıkan özellikleridir.': 'La marche, les premiers mots et l\'envie d\'autonomie marquent cette étape.',
  'Yürüteç kullanma: düşme ve yaralanma riskini artırır.': 'N\'utilisez pas de trotteur : il augmente le risque de chutes et de blessures.',
  'Yürüyüş, yüzme, sabit bisiklet ve gebe yogası güvenli seçeneklerdir.': 'Marche, natation, vélo d\'appartement et yoga prénatal sont des choix sûrs.',
  'Yürüyüşle başlayıp yavaş yavaş artır.': 'Commencez par la marche et augmentez progressivement.',
  'Yüz ifadeleri başlayabilir; vücudu ince tüylerle (lanugo) kaplanmaya başlar.': 'Les expressions du visage peuvent apparaître ; le corps se couvre d\'un fin duvet (lanugo).',
  'Yüz ifadelerini keşfet': 'Découvrir les expressions du visage',
  'Yüz temizliği, nemlendirme ve güneşten korunmayı üç kısa adıma bölün. Yeni ürünleri tek tek ekleyerek cildinizin tepkisini gözlemleyin.': 'Divisez nettoyage, hydratation et protection solaire en trois étapes courtes. Ajoutez les nouveaux produits un par un et observez la réaction de votre peau.',
  'Yüz ve ellerde ani şişlik, nefes darlığı: hemen başvur.': 'Gonflement soudain du visage et des mains, essoufflement : demandez de l\'aide immédiatement.',
  'Yüz-dil şişmesi, solunum güçlüğü veya baygınlık gibi bulgular acil değerlendirme gerektirir.': 'Des signes comme un gonflement du visage ou de la langue, une difficulté à respirer ou un malaise nécessitent une évaluation en urgence.',
