  'ÖNEMLİ: Ek gıdaya genellikle yaklaşık 6. ayda, gelişimsel hazır oluşa göre başlanır. 12 aydan önce bal vermeyin; tuz ve şeker eklemeyin. Bütün kuruyemişler ve sert/yuvarlak parçalar boğulma riski taşır. Alerjenleri kontrol edin, yiyecekleri uygun kıvamda sunun ve bebeği yemek sırasında yalnız bırakmayın.': 'IMPORTANT : la diversification commence généralement vers 6 mois, selon la maturité du développement. Pas de miel avant 12 mois ; n\'ajoutez ni sel ni sucre. Les noix entières et les morceaux durs/ronds présentent un risque d\'étouffement. Faites attention aux allergènes, proposez une texture adaptée et ne laissez jamais votre bébé seul pendant qu\'il mange.',
