  'İhtiyaçlarınızı açık ve saygılı biçimde ifade etmeye çalışın. Yapamayacağınız işlere hemen söz vermek zorunda değilsiniz.': 'Essayez d\'exprimer vos besoins clairement et avec respect. Vous n\'êtes pas obligée de promettre tout de suite ce que vous ne pouvez pas faire.',
  'İhtişam, gösteriş': 'Splendeur, faste',
  'İki adımlı küçük görevler ekleyin; başarıyı değil keşfi öne çıkarın.': 'Ajoutez de petites tâches en deux étapes ; privilégiez la découverte plutôt que la réussite.',
  'İki aşamalı basit yönergeleri, hayalî oyunu ve sosyal etkileşimi birlikte deneyimleyin.': 'Essayez ensemble des consignes simples en deux étapes, le faire-semblant et l\'interaction sociale.',
  'İki blok üst üste koyma, büyük boya kalemiyle karalama (gözetimli), saklambaç benzeri basit oyunlar.': 'Empiler deux cubes, gribouiller avec un gros crayon (sous surveillance), jeux de cache-cache simples.',
  'İki dilli büyüyen çocuklarda kelime dağarcığı iki dile dağılabilir; bu gecikme anlamına gelmez.': 'Les enfants bilingues peuvent répartir leur vocabulaire entre deux langues ; ce n\'est pas un retard.',
  'İki elle tutulacak oyuncaklar, birbirine vurma (ritim), aynada yüz ifadeleri.': 'Jouets à tenir à deux mains, taper des objets l\'un contre l\'autre (rythme), expressions du visage devant le miroir.',
  'İki forumun SQL dosyaları, RLS politikaları ve çok kullanıcılı testleri gerekli.': 'Des fichiers SQL, des règles RLS et des tests multi-utilisateurs pour les deux forums sont nécessaires.',
  'İki forumun canlı Supabase bağlantısı ve RLS politikaları doğrulandı': 'La connexion Supabase en direct et les règles RLS des deux forums ont été vérifiées',
  'İki haftadan uzun süren mutsuzluk, ilgi kaybı, umutsuzluk.': 'Tristesse, perte d\'intérêt ou désespoir pendant plus de deux semaines.',
  'İki haftadan uzun süren mutsuzluk, umutsuzluk, uykusuzluk.': 'Tristesse, désespoir ou insomnie pendant plus de deux semaines.',
  'İki sözcüklü cümleler yaygınlaşır; 50 civarı sözcük olağandır. Taklit ve hayali oyun artar.': 'Les phrases de deux mots deviennent fréquentes ; environ 50 mots, c\'est normal. L\'imitation et le faire-semblant augmentent.',
  'İki tarafını da içi tamamen pişene dek pişirin.': 'Faites cuire des deux côtés jusqu’à cuisson complète.',
  'İki tarafını da içi tamamen pişene kadar çevirerek pişirin.': 'Retournez et faites cuire les deux faces jusqu’à cuisson complète.',
  'İki tarafını da içi tamamen pişene kadar çevirin.': 'Retournez jusqu’à cuisson complète des deux côtés.',
  'İki tarafını da yumurta tamamen pişene kadar pişirin.': 'Faites cuire des deux côtés jusqu’à ce que l’œuf soit bien cuit.',
  'İki yaş: koşar, top atar, 2–3 sözcüklü cümleler kurar, basit iki aşamalı yönergeleri yapar. Tuvalet eğitimine hazırlık belirtileri görülebilir.': 'Deux ans : court, lance un ballon, fait des phrases de 2–3 mots, suit des consignes simples en deux étapes. Des signes de maturité pour la propreté peuvent apparaître.',
  'İki yüzünü de içi pişene kadar orta ateşte kızartın.': 'Faites dorer les deux côtés à feu moyen jusqu’à cuisson complète.',
  'İki yüzünü de yumurta tamamen pişene kadar pişirin.': 'Faites cuire des deux côtés jusqu’à cuisson complète de l’œuf.',
