  'İlaç ve temizlik ürünlerini kilitli dolapta sakla; zehirlenmede 114. Sıcak içecekleri ve tencere saplarını ulaşamayacağı yerde tut. Su kenarında kol mesafesinde ol.': 'Rangez médicaments et produits ménagers sous clé ; en cas d\'intoxication, appelez le centre antipoison. Gardez boissons chaudes et queues de casserole hors de portée. Restez à portée de bras près de l\'eau.',
