  'İlaç, temizlik ürünü veya bitki yutulması çocuklarda sık görülen acil durumlardandır.': 'L\'ingestion de médicaments, de produits ménagers ou de plantes est une urgence fréquente chez l\'enfant.',
  'İlaçları ve temizlik ürünlerini kilitli, yüksek dolaplarda orijinal kutusunda sakla.': 'Rangez médicaments et produits ménagers dans leur emballage d\'origine, sous clé et en hauteur.',
  'İlaçları yalnızca yaşa, kiloya ve hekim önerisine uygun şekilde kullanın.': 'Utilisez les médicaments uniquement selon l\'âge, le poids et l\'avis du médecin.',
  'İlaçları çocukların erişemeyeceği güvenli bir yerde saklayın.': 'Rangez les médicaments en lieu sûr, hors de portée des enfants.',
  'İlaçları, temizlik ürünlerini ve küçük nesneleri erişimden uzak tutun. Yaşa uygun oto koltuğu kullanın.': 'Gardez médicaments, produits ménagers et petits objets hors de portée. Utilisez un siège auto adapté à l\'âge.',
  'İlerlemeyi mükemmellik üzerinden değerlendirmeyin.': 'Ne jugez pas vos progrès à l\'aune de la perfection.',
