  'İletişimde kalmak istediğiniz kişileri belirleyin. Düzenli kısa görüşmeler için uygun zamanlar planlayın.': 'Identifiez les personnes avec qui vous voulez rester en contact. Prévoyez des moments pour de courts échanges réguliers.',
  'İlgilendiğiniz bir konu seçin. Her gün kısa okuma veya uygulama zamanı ayırın. Öğrendiklerinizi kendi cümlelerinizle not edin.': 'Choisissez un sujet qui vous intéresse. Réservez chaque jour un court moment pour lire ou pratiquer. Notez ce que vous apprenez avec vos mots.',
